from pathlib import Path
for name in ['summary.txt', 'table.csv', 'chart.py']:
    print(f'\n--- {name} ---\n{Path(name).read_text()}')

table = pd.read_csv('table.csv')
expected = {
    row.Sector: row.Change * (-1 if row.Direction == 'Decrease' else 1)
    for row in table.itertuples()
}
actual = {
    sector: float(negative + positive)
    for sector, negative, positive in zip(fig.data[0].y, fig.data[0].x, fig.data[1].x)
}
assert actual == expected, (actual, expected)
assert fig.data[0].marker.color == '#EF553B'
assert fig.data[1].marker.color == '#00CC96'
assert fig.layout.width == 800 and fig.layout.height == 500
assert Path('output.png').is_file()
print('Verified all plotted values against table.csv. Corrected chart saved as output.png.')
